#include <pqxx/pqxx>
#include <cstdlib>
#include <exception>
#include <iostream>

// One attempt, not an idempotent HTTP booking endpoint.
int main() {
    const char* config = std::getenv("CPP_COURSE_DB");
    if (config == nullptr || *config == '\0') {
        std::cerr << "Set CPP_COURSE_DB.\n";
        return 1;
    }
    try {
        pqxx::connection connection{config};
        pqxx::work transaction{connection};
        const auto result = transaction.exec(
            "UPDATE parking SET available = available - 1 "
            "WHERE id = $1 AND available > 0 RETURNING available",
            pqxx::params{1});
        if (result.empty()) {
            std::cout << "not_reserved: full or absent\n";
            return 2;
        }
        const int remaining = result[0][0].as<int>();
        transaction.commit();
        std::cout << "reserved; remaining=" << remaining << '\n';
        return 0;
    } catch (const pqxx::in_doubt_error&) {
        std::cerr << "Commit outcome unknown; do not blindly retry.\n";
        return 3;
    } catch (const pqxx::sql_error& error) {
        std::cerr << "SQLSTATE=" << error.sqlstate() << '\n';
        return 4;
    } catch (const std::exception&) {
        std::cerr << "Database operation failed; investigate before retrying.\n";
        return 5;
    }
}

CREATE TABLE outbox_demo_tasks (
    id bigint PRIMARY KEY,
    owner_id bigint NOT NULL,
    done boolean NOT NULL,
    version bigint NOT NULL CHECK (version > 0)
);
CREATE TABLE outbox_demo_events (
    event_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    task_id bigint NOT NULL REFERENCES outbox_demo_tasks(id),
    task_version bigint NOT NULL,
    payload jsonb NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    sent_at timestamptz,
    UNIQUE (task_id, task_version)
);
INSERT INTO outbox_demo_tasks VALUES (10, 1, false, 1);

BEGIN;
WITH changed AS (
    UPDATE outbox_demo_tasks
    SET done = true, version = version + 1
    WHERE id = 10 AND owner_id = 1 AND version = 1 AND done = false
    RETURNING id, version
)
INSERT INTO outbox_demo_events (task_id, task_version, payload)
SELECT id, version,
       jsonb_build_object('task_id', id, 'version', version, 'done', true)
FROM changed
RETURNING event_id, task_id, task_version;
COMMIT;

SELECT id, done, version FROM outbox_demo_tasks;
SELECT event_id, task_id, task_version, sent_at FROM outbox_demo_events;

CREATE TABLE inbox_demo_receipts (
    consumer text NOT NULL,
    event_id bigint NOT NULL,
    PRIMARY KEY (consumer, event_id)
);
CREATE TABLE inbox_demo_totals (
    id integer PRIMARY KEY,
    completed bigint NOT NULL CHECK (completed >= 0)
);
INSERT INTO inbox_demo_totals VALUES (1, 0);

BEGIN;
WITH first_delivery AS (
    INSERT INTO inbox_demo_receipts (consumer, event_id)
    VALUES ('completed-counter-v1', 42)
    ON CONFLICT (consumer, event_id) DO NOTHING
    RETURNING event_id
)
UPDATE inbox_demo_totals
SET completed = completed + (SELECT count(*) FROM first_delivery)
WHERE id = 1
RETURNING completed;
COMMIT;
